/*
 * saml_service_provider_config.h
 *
 * Service-provider configuration, generated by the server. Never includes the private key.
 */

#ifndef _saml_service_provider_config_H_
#define _saml_service_provider_config_H_

#include <string.h>
#include "../external/cJSON.h"
#include "../include/list.h"
#include "../include/keyValuePair.h"
#include "../include/binary.h"

typedef struct saml_service_provider_config_t saml_service_provider_config_t;




typedef struct saml_service_provider_config_t {
    char *sso_url; // string
    char *public_certificate; // string
    char *audience_url; // string

    int _library_owned; // Is the library responsible for freeing this object?
} saml_service_provider_config_t;

__attribute__((deprecated)) saml_service_provider_config_t *saml_service_provider_config_create(
    char *sso_url,
    char *public_certificate,
    char *audience_url
);

void saml_service_provider_config_free(saml_service_provider_config_t *saml_service_provider_config);

saml_service_provider_config_t *saml_service_provider_config_parseFromJSON(cJSON *saml_service_provider_configJSON);

cJSON *saml_service_provider_config_convertToJSON(saml_service_provider_config_t *saml_service_provider_config);

#endif /* _saml_service_provider_config_H_ */

